---- MODULE W4Od9m4p2t2 ----
EXTENDS Naturals, FiniteSets, TLC

CONSTANTS Feeders, CAP, Total

Load == (1 :> 3) @@ (2 :> 2) @@ (3 :> 4)

RECURSIVE SumLoad(_)
SumLoad(S) == IF S = {} THEN 0
              ELSE LET x == CHOOSE y \in S : TRUE IN Load[x] + SumLoad(S \ {x})

VARIABLES online, pending, shedA, shedB

vars == <<online, pending, shedA, shedB>>

Init ==
    /\ online = Feeders
    /\ pending = {}
    /\ shedA = {}
    /\ shedB = {}

RequestShed ==
    /\ Cardinality(pending) < CAP
    /\ \E f \in online :
         /\ online' = online \ {f}
         /\ pending' = pending \cup {f}
    /\ UNCHANGED <<shedA, shedB>>

TripA ==
    /\ \E f \in pending :
         /\ pending' = pending \ {f}
         /\ shedA' = shedA \cup {f}
    /\ UNCHANGED <<online, shedB>>

TripB ==
    /\ \E f \in pending :
         /\ pending' = pending \ {f}
         /\ shedB' = shedB \cup {f}
    /\ UNCHANGED <<online, shedA>>

Restore ==
    /\ \E f \in shedA \cup shedB :
         /\ shedA' = shedA \ {f}
         /\ shedB' = shedB \ {f}
         /\ online' = online \cup {f}
    /\ UNCHANGED pending

Quiesce ==
    /\ online = {}
    /\ pending = {}
    /\ UNCHANGED vars

Next == RequestShed \/ TripA \/ TripB \/ Restore \/ Quiesce

Spec == Init /\ [][Next]_vars

LoadConserved ==
    SumLoad(online) + SumLoad(pending) + SumLoad(shedA) + SumLoad(shedB) = Total
====

